  ('38529dc6-9cde-5eb7-9912-f2b8b3e59531', null, (select id from public.skills where slug = 'modifier-placement'), null, 'medium',
   $q$Which sentence says that the bus left the station a moment ago?$q$, $q$[{"text":"The bus left the station, just.","is_correct":false,"misconception_token":"just-at-end"},{"text":"Just the bus left the station.","is_correct":false,"misconception_token":"just-modifies-subject"},{"text":"The bus just left the station.","is_correct":true},{"text":"The bus left just the station.","is_correct":false,"misconception_token":"just-modifies-object"}]$q$::jsonb, $q$The bus just left the station.$q$, $q$Placed right before the verb, "just" means a moment ago. "Just the bus" means only the bus, so it answers a different question about which vehicles left.$q$, 'draft', null)
